package co.aplomo.web;
import co.aplomo.modelo.*;import co.aplomo.soporte.*;import co.aplomo.servicio.*;import co.aplomo.dao.*;import org.junit.jupiter.api.*;import org.junit.jupiter.params.ParameterizedTest;import org.junit.jupiter.params.provider.*;import java.util.*;import java.util.regex.*;import java.net.*;import java.net.http.*;import static org.junit.jupiter.api.Assertions.*;
/** RF-024, RF-002, RNF-004/006: listas y direcciones directas de dos empresas y un Rojo En curso. */
class HttpConsultasTest extends HttpPrueba {
    EscenarioConsultas e;
    @BeforeEach void escenario()throws Exception{e=new EscenarioConsultas(this,carpetaFotos);entrar(usuario);}
    private int idAjeno(SeccionConsulta s){return switch(s){case EMPRESAS->e.empresaB;case SEDES->e.sedeB;case SALONES->e.salonB;case AREAS->e.areaB;case CARGOS->e.cargoB;case PUESTOS->e.puestoB;case RESERVAS->e.reservaB;case VISITAS->e.visitaB;case EVALUACIONES->e.evalB;case PENDIENTES->e.pendienteB;case SUGERENCIAS->e.sugerenciaB;};}
    @ParameterizedTest @EnumSource(SeccionConsulta.class) void listasDelUsuarioNoExponenEmpresaAjenaNiAcciones(SeccionConsulta s)throws Exception{var r=get(s.ruta());assertEquals(200,r.statusCode(),r.body());assertTrue(r.body().contains("Aplicar filtros"));if(s==SeccionConsulta.PENDIENTES)assertTrue(r.body().contains("<span class=\"eyebrow\">Seguimiento</span>"));assertFalse(r.body().contains("Empresa ajena QA"));assertFalse(r.body().contains("Área ajena QA"));assertFalse(r.body().contains("Cargo ajeno QA"));for(String texto:List.of("Nueva empresa","Nueva reserva","Escribir sugerencia","Editar sugerencia","Quitar sugerencia","Marcar como arreglado"))assertFalse(r.body().contains(texto));assertFalse(r.body().contains("/fotos/"));assertEquals(403,get(s.ruta()+"?empresa="+e.empresaB).statusCode());}
    @ParameterizedTest @EnumSource(SeccionConsulta.class) void direccionesDirectasDeOtraEmpresaSeDeniegan(SeccionConsulta s)throws Exception{var r=get(s.ruta()+"/"+idAjeno(s));assertEquals(403,r.statusCode());assertTrue(r.body().contains("Acceso denegado")||r.body().contains("no está disponible"));}
    @ParameterizedTest @ValueSource(strings={"visita","evaluacion","pendiente","sugerencia","foto"}) void rojoEnCursoSeDeniegaPorDireccionDirecta(String tipo)throws Exception{String ruta=switch(tipo){case "visita"->"/visitas/"+e.visitaAbierta;case "evaluacion"->"/evaluaciones/"+e.evalAbierta;case "pendiente"->"/pendientes/"+e.pendienteAbierto;case "sugerencia"->"/sugerencias/"+e.sugerenciaAbierta;default->"/fotos/"+new EvaluacionDao().fotos(con,e.evalAbierta).get(0).id();};assertEquals(403,get(ruta).statusCode());}
    @Test void evaluacionFinalizadaAbreSinFotosYLosPuntajesAbiertosNoSeFiltran()throws Exception{var r=get("/evaluaciones/"+e.evalVerde);assertEquals(200,r.statusCode());assertTrue(r.body().contains("2 · Verde · Nivel 1"));assertFalse(r.body().contains("/fotos/"));assertFalse(r.body().contains("Evaluar puesto"));assertFalse(r.body().contains("Guardar análisis"));var puestos=get("/puestos");String uno=fila(puestos.body(),e.puesto1),dos=fila(puestos.body(),e.puesto2);assertTrue(uno.contains("2 · Verde · Nivel 1"));assertFalse(uno.contains("7 · Rojo"));assertTrue(dos.contains("Sin resultado"));assertFalse(dos.contains("7 · Rojo"));assertTrue(get("/salones/"+e.salonA).body().contains("2 · Verde · Nivel 1"));assertEquals(403,get("/evaluaciones?visita="+e.visitaAbierta).statusCode());}
    @Test void reservasPropiasSeConsultanEnTodosLosEstadosIncluidoMotivo()throws Exception{for(int id:new int[]{e.reservaFinal,e.reservaAbierta,e.reservaEsperando,e.reservaCancelada}){var r=get("/reservas/"+id);assertEquals(200,r.statusCode());assertFalse(r.body().contains("Editar reserva"));assertFalse(r.body().contains("Aceptar reserva"));assertFalse(r.body().contains("Cancelar reserva"));assertFalse(r.body().contains("Iniciar visita"));}assertTrue(get("/reservas/"+e.reservaCancelada).body().contains("La empresa solicitó otro horario."));assertFalse(get("/reservas/"+e.reservaAbierta).body().contains("/visitas/"+e.visitaAbierta));assertEquals(1,contarFilas(get("/reservas?estado=CANCELADA").body()));}
    @Test void filtrosCombinadosYOrdenDeCabeceraConservanLaConsulta()throws Exception{String ruta="/evaluaciones?empresa="+e.empresaA+"&sede="+e.sedeA+"&salon="+e.salonA+"&area="+e.areaA+"&cargo="+e.cargoA+"&numero=3&puntaje=7&color=ROJO&nivel=4&desde=2026-11-10&hasta=2026-11-10&estado=FINALIZADA&q=ensamble";var r=get(ruta);assertEquals(200,r.statusCode());assertEquals(1,contarFilas(r.body()));assertTrue(r.body().contains("data-registro=\""+e.evalRojo+"\""));var m=Pattern.compile("class=\"orden-columna\" href=\"([^\"]+)\"").matcher(r.body());assertTrue(m.find());String enlace=m.group(1).replace("&amp;","&");assertTrue(enlace.contains("color=ROJO"));assertTrue(enlace.contains("q=ensamble"));assertTrue(enlace.contains("numero=3"));assertEquals(200,get(enlace).statusCode());assertEquals(1,contarFilas(get(enlace).body()));}
    @Test void sinCoincidenciasMuestraCeroYTextoHtmlSeEscapa()throws Exception{var r=get("/empresas?q="+URLEncoder.encode("<script>texto</script>",java.nio.charset.StandardCharsets.UTF_8));assertEquals(200,r.statusCode());assertTrue(r.body().contains("0 resultados"));assertTrue(r.body().contains("&lt;script&gt;texto&lt;/script&gt;"));assertFalse(r.body().contains("<script>texto"));assertEquals(400,get("/evaluaciones?orden=nombre%3BDELETE").statusCode());assertEquals(400,get("/evaluaciones?desde=incorrecta").statusCode());}
    @Test void listaDeUnaEvaluacionOcultaPuestoYLaGeneralLoConserva()throws Exception{var particular=get("/sugerencias?evaluacion="+e.evalRojo);assertEquals(200,particular.statusCode());assertFalse(particular.body().contains("aria-label=\"Ordenar por Puesto\""));assertTrue(get("/sugerencias").body().contains("aria-label=\"Ordenar por Puesto\""));assertTrue(particular.body().contains("11 sugerencias"));}
    @Test void administradorVeRojoAbiertoYConservaSusAcciones()throws Exception{cliente=HttpClient.newBuilder().cookieHandler(new CookieManager(null,CookiePolicy.ACCEPT_ALL)).build();entrar(admin);assertEquals(200,get("/evaluaciones/"+e.evalAbierta).statusCode());assertTrue(get("/evaluaciones/"+e.evalAbierta).body().contains("/fotos/"));assertTrue(get("/empresas").body().contains("Nueva empresa"));assertTrue(get("/sugerencias?evaluacion="+e.evalRojo).body().contains("Escribir sugerencia"));assertTrue(get("/pendientes/"+e.pendienteAbierto).body().contains("Marcar como arreglado"));assertTrue(get("/evaluaciones?estado=EN_CURSO&empresa="+e.empresaA).body().contains("7 · Rojo · Nivel 4"));}
    private static String fila(String h,int id){var m=Pattern.compile("<tr data-registro=\""+id+"\">(.*?)</tr>",Pattern.DOTALL).matcher(h);assertTrue(m.find());return m.group(1);}
    private static int contarFilas(String h){return (int)Pattern.compile("<tr data-registro=").matcher(h).results().count();}
}
